import { numeric, timestamp, uuid } from 'drizzle-orm/pg-core';

/** Primary key: random UUID generated by Postgres. */
export const pk = () => uuid('id').primaryKey().defaultRandom();

/** Money is numeric(12,2) in ₹ (see PLAN.md §4). Read as a JS number; round with `round2` before writing. */
export const money = (name: string) => numeric(name, { precision: 12, scale: 2, mode: 'number' });

/** Percentages such as GST rates (e.g. 5.00, 18.00). */
export const percent = (name: string) => numeric(name, { precision: 5, scale: 2, mode: 'number' });

export const createdAt = () => timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow();
export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true, mode: 'date' })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
